insert into public.posts (slug, category, cover, title, lead, body, score, venue_id, status, published_at) values
  ('satama-recenzja', 'Recenzja', 'pc1', 'Rzymski przepych, który działa nie tylko na Instagramie', 'Colosseum Sauna Arena robi wrażenie skalą, ale prawdziwą wartością są ceremonie i obsługa.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Satama to obiekt, który łatwo sprowadzić do efektownych zdjęć — antyczne kolumny, ogromna arena, para unosząca się pod sklepieniem. Byłoby jednak krzywdzące zatrzymać się na warstwie wizualnej."}]},{"type":"paragraph","content":[{"type":"text","text":"Program ceremonii jest gęsty i różnorodny, a saunamistrzowie prowadzą seans jak spektakl — z narracją, muzyką i wyczuciem temperatury. Strefa banii i rytuał z wenikiem to mocne punkty. Widać, że obiekt traktuje aufguss jako sztukę, nie dodatek do basenu."}]},{"type":"paragraph","content":[{"type":"text","text":"Kontekst też robi swoje: jezioro Scharmützelsee tuż obok sprawia, że schłodzenie po saunie staje się osobnym przeżyciem. Latem to jeden z najlepszych powodów, by tu przyjechać."}]},{"type":"paragraph","content":[{"type":"text","text":"Minusy? W szczycie weekendu bywa tłoczno, a część seansów wymaga wcześniejszej rezerwacji. Mimo to — jeden z najlepszych obiektów aufguss w Europie, do którego chce się wracać."}]}]}'::jsonb, 8.8, 55, 'published', now()),
  ('liquidrom-recenzja', 'Recenzja', 'pc2', 'Berliński minimalizm pod wodą', 'Kultowa architektura i podwodna muzyka, ale program aufguss bywa nierówny.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Liquidrom to instytucja — basen solankowy pod betonową kopułą z muzyką słyszalną pod wodą robi wrażenie za każdym razem. To miejsce, które w Berlinie stało się synonimem miejskiego relaksu."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufguss? Wieczorami potrafi być znakomity, prowadzony z wyczuciem i pomysłem. W ciągu dnia poziom bywa jednak nierówny — czasem to raczej rutynowy seans niż ceremonia."}]},{"type":"paragraph","content":[{"type":"text","text":"To miejsce bardziej o atmosferze i wyciszeniu niż o ceremonialnym show. Jeśli szukasz spokoju w centrum miasta — trafisz idealnie. Jeśli wielkiego widowiska — bywa różnie."}]}]}'::jsonb, 7.9, 111, 'published', now()),
  ('termy-rzymskie-recenzja', 'Recenzja', 'pc3', 'Arena, która podniosła poprzeczkę całej Europie', 'Najlepszy program ceremonii w Polsce i sceneria, która robi robotę nawet przy pustej widowni.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Są obiekty, które budują wrażenie scenografią, i takie, które budują je poziomem seansów. Termy Rzymskie należą do rzadkiej grupy, w której obie te rzeczy grają na jedną nutę. Rzymska stylistyka mogłaby łatwo osunąć się w kicz, a jednak trzyma proporcje i pracuje na atmosferę zamiast ją przykrywać."}]},{"type":"paragraph","content":[{"type":"text","text":"Najważniejsze dzieje się jednak w grafiku. Program ceremonii jest gęsty, prowadzony przez saunamistrzów z międzynarodowym doświadczeniem, a różnica między seansem porannym a wieczornym jest tu kwestią repertuaru, nie jakości. To rzadkość — w większości dużych obiektów popołudnie bywa najsłabszą częścią dnia."}]},{"type":"paragraph","content":[{"type":"text","text":"Osobny rozdział to wielkie wydarzenia. Obiekt potrafi obsłużyć turniejową publiczność bez rozsypania codziennego harmonogramu, co przy tej skali jest osiągnięciem organizacyjnym samym w sobie."}]},{"type":"paragraph","content":[{"type":"text","text":"Zastrzeżenie mam jedno, za to realne: w weekendy popularność potrafi przełożyć się na kolejki do najbardziej obleganych seansów. Warto planować wizytę w tygodniu — wtedy to po prostu najlepszy adres aufguss w kraju."}]}]}'::jsonb, 9.2, 13, 'published', now()),
  ('loyly-recenzja', 'Recenzja', 'pc4', 'Fińska szczerość, czyli sauna bez scenografii', 'Żadnych efektów specjalnych — drewno, ogień i Bałtyk kilka kroków dalej.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Löyly Helsinki jest przeciwieństwem wszystkiego, co zwykle chwalę w wielkich obiektach aufguss. Nie ma tu areny, choreografii ani muzyki budującej napięcie. Jest drewno, dym, gorąco i morze, do którego schodzi się po schodkach prosto z tarasu."}]},{"type":"paragraph","content":[{"type":"text","text":"I właśnie dlatego to miejsce trafia na tak wysokie miejsce. Fińska szkoła traktuje saunę jako codzienność, nie jako spektakl — a poziom rzemiosła, czyli jakość pary i praca z piecem, jest tu wzorcowy. Sauna dymna to doświadczenie, którego nie zastąpi żaden program ceremonii."}]},{"type":"paragraph","content":[{"type":"text","text":"Architektura zasługuje na osobne zdanie: drewniany, falujący budynek nad zatoką jest publicznie dostępny także dla osób, które przyszły tylko na kawę. To rzadki przykład obiektu wpisanego w miasto, a nie odgrodzonego od niego."}]},{"type":"paragraph","content":[{"type":"text","text":"Dla kogo to nie będzie? Dla szukających klasycznego aufguss z ręcznikiem i show. Tego tu po prostu nie ma i nie ma być."}]}]}'::jsonb, 9, 105, 'published', now()),
  ('chocholowskie-recenzja', 'Recenzja', 'pc1', 'Tatry za oknem i seanse, które trzymają równy poziom', 'Przewidywalnie dobry program i widok, który sam w sobie jest połową wrażenia.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chochołowskie Termy mają atut nie do skopiowania: panoramę Tatr z saun i stref wypoczynku. Brzmi jak dodatek marketingowy, ale realnie zmienia odbiór seansu — schłodzenie z takim widokiem zostaje w pamięci dłużej niż niejeden efektowny aufguss."}]},{"type":"paragraph","content":[{"type":"text","text":"Program ceremonii jest solidny i, co ważniejsze, powtarzalny. Nie trafiłem tu jeszcze na seans słaby, choć nie trafiłem też na taki, który by mnie całkowicie zaskoczył. To obiekt równy, dobrze prowadzony, z saunamistrzami rozumiejącymi, że publiczność górska bywa inna niż wielkomiejska."}]},{"type":"paragraph","content":[{"type":"text","text":"Strefa saun jest przemyślana, a rytuały autorskie coraz odważniejsze — widać, że obiekt inwestuje w ludzi, nie tylko w infrastrukturę."}]},{"type":"paragraph","content":[{"type":"text","text":"Minus? Sezonowość. W szczycie ferii i długich weekendów tłok potrafi zjeść sporo z tego spokoju, za który się tu przyjeżdża."}]}]}'::jsonb, 8.6, 14, 'published', now()),
  ('vabali-recenzja', 'Recenzja', 'pc2', 'Balijska sceneria w środku Berlina', 'Ogromny wybór saun i konsekwentnie utrzymany klimat, choć aufguss bywa zachowawczy.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Vabali to popis budowania nastroju. Drewno, woda, zieleń i architektura inspirowana Bali sprawiają, że po kilkunastu minutach zapomina się, że za płotem jest wielkie miasto. Konsekwencja tej scenografii robi w Berlinie różnicę."}]},{"type":"paragraph","content":[{"type":"text","text":"Wybór saun jest imponujący i dobrze rozłożony — od łagodnych po naprawdę mocne, z sensownymi strefami ciszy pomiędzy. Obsługa pilnuje reguł, dzięki czemu spokój nie jest tu deklaracją, tylko stanem faktycznym."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufguss stoi na przyzwoitym, wyrównanym poziomie, ale rzadko wychodzi poza sprawdzony schemat. To ceremonie poprawne i przyjemne, tylko niekoniecznie takie, o których opowiada się potem znajomym."}]},{"type":"paragraph","content":[{"type":"text","text":"Jeśli szukasz całodniowego wyciszenia w wysokim standardzie — trafiłeś idealnie. Jeśli mistrzowskiego show — celuj gdzie indziej."}]}]}'::jsonb, 8.5, 61, 'published', now()),
  ('bussloo-recenzja', 'Recenzja', 'pc3', 'Holenderska szkoła ceremonii w kameralnym wydaniu', 'Świetna strefa zewnętrzna i aufguss prowadzony z wyczuciem, bez przesadnego rozmachu.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Holandia od lat gra w aufguss w pierwszej lidze i Thermen Bussloo dobrze tłumaczy dlaczego. Ceremonie prowadzone są tu z wyczuciem tempa i temperatury, a saunamistrzowie potrafią pracować z publicznością zamiast po prostu odrobić program."}]},{"type":"paragraph","content":[{"type":"text","text":"Duży plus za strefę zewnętrzną — sauny wtopione w zieleń i przestrzeń do schłodzenia, która nie sprowadza się do jednego zimnego prysznica. To właśnie tam obiekt jest najlepszy."}]},{"type":"paragraph","content":[{"type":"text","text":"Skala jest średnia i to działa na korzyść: kameralność sprzyja kontaktowi między prowadzącym a gośćmi, czego w wielkich arenach często brakuje."}]},{"type":"paragraph","content":[{"type":"text","text":"Cena za wstęp należy do wyższych w regionie, a dla gościa z zagranicy dochodzi bariera językowa przy części seansów tematycznych. Warto o tym wiedzieć przed wizytą."}]}]}'::jsonb, 8.4, 76, 'published', now()),
  ('suntago-recenzja', 'Recenzja', 'pc4', 'Skala, która wreszcie pracuje na jakość', 'Największy obiekt w regionie coraz poważniej traktuje sauny — i widać to w programie.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Suntago długo kojarzyło się przede wszystkim z częścią wodną i rodzinną rozrywką. Strefa saunowa przez ten cień się przebijała, ale ostatnie sezony wyraźnie zmieniły proporcje: program ceremonii jest dziś obszerny, a saunamistrzowie mają wyraźnie więcej do powiedzenia."}]},{"type":"paragraph","content":[{"type":"text","text":"Wielkość obiektu przestała być wadą. Sauny tematyczne trzymają poziom, strefa dla dorosłych jest realnie oddzielona, a rozmach pozwala na seanse dla dużej widowni bez ścisku w kabinie."}]},{"type":"paragraph","content":[{"type":"text","text":"To wciąż nie jest miejsce na kameralne wyciszenie — do Suntago przyjeżdża się po energię i różnorodność, nie po ciszę."}]},{"type":"paragraph","content":[{"type":"text","text":"Największe zastrzeżenie dotyczy godzin szczytu: w weekendy część atrakcji obsługiwana jest w tempie, które odbija się na spokoju seansu. W tygodniu obiekt wypada wyraźnie lepiej."}]}]}'::jsonb, 8.1, 20, 'published', now()),
  ('aquapalace-recenzja', 'Recenzja', 'pc1', 'Czeska szkoła aufguss w solidnym wydaniu', 'Mocna kadra saunamistrzów i porządny warsztat, choć obiekt bywa przytłoczony ruchem.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Czechy mają jedną z najmocniejszych scen aufguss w Europie i Aquapalace Praha regularnie tę tezę potwierdza. Warsztat prowadzących jest tu wysoki: praca ręcznikiem czysta, dobór aromatów przemyślany, tempo seansu budowane świadomie."}]},{"type":"paragraph","content":[{"type":"text","text":"Strefa saunowa jest dobrze zaprojektowana, z sensownym rozkładem temperatur i miejscem na odpoczynek między ceremoniami. Widać szkołę, w której technika liczy się bardziej niż efekt."}]},{"type":"paragraph","content":[{"type":"text","text":"Obiekt pełni jednak podwójną rolę — dużego aquaparku i poważnego adresu saunowego jednocześnie. To bywa odczuwalne, zwłaszcza w weekendy, gdy ruch w części wodnej przenika do strefy ciszy."}]},{"type":"paragraph","content":[{"type":"text","text":"Mimo to dla kogoś, kto chce zobaczyć czeski aufguss bez wyprawy w mniejsze miasta, to najprostszy i bardzo dobry wybór."}]}]}'::jsonb, 8, 32, 'published', now()),
  ('aqua-dome-recenzja', 'Recenzja', 'pc2', 'Alpejska panorama, która zmienia sens schłodzenia', 'Widok i termy w najwyższej lidze, program ceremonii już niekoniecznie.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aqua Dome sprzedaje przede wszystkim położenie i trudno mieć o to pretensję — alpejskie otoczenie sprawia, że wyjście z sauny na mróz staje się osobną atrakcją. Pod tym względem niewiele obiektów w Europie może się równać."}]},{"type":"paragraph","content":[{"type":"text","text":"Sama infrastruktura termalna jest znakomita: baseny, strefy relaksu i zaplecze utrzymane w standardzie, którego oczekuje się w tej cenie."}]},{"type":"paragraph","content":[{"type":"text","text":"Aufguss wypada jednak blado na tle otoczenia. Ceremonie są poprawne, ale rzadko wychodzą poza rutynę, a repertuar bywa powtarzalny. To obiekt termalny z saunami, nie obiekt saunowy z termami — i tę różnicę czuć w programie."}]},{"type":"paragraph","content":[{"type":"text","text":"Przyjeżdżaj dla gór i wody. Jeśli aufguss jest dla ciebie najważniejszy, potraktuj go tu jako miły dodatek, a nie powód wyjazdu."}]}]}'::jsonb, 7.8, 92, 'published', now()),
  ('thermae-2000-recenzja', 'Recenzja', 'pc3', 'Klasyk z Limburgii, który potrzebuje odświeżenia', 'Wciąż przyjemny i dobrze prowadzony, ale konkurencja przez ostatnie lata pojechała dalej.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Thermae 2000 przez lata było punktem odniesienia w Beneluksie i wciąż ma sporo z dawnej klasy: położenie na wzgórzu, panoramiczne widoki i spokojną, dojrzałą publiczność, która wie, po co przyszła."}]},{"type":"paragraph","content":[{"type":"text","text":"Ceremonie prowadzone są kompetentnie, bez fajerwerków, ale i bez wpadek. Strefa saun zachowuje przyjemny rytm dnia, a obsługa dba o reguły ciszy."}]},{"type":"paragraph","content":[{"type":"text","text":"Problem w tym, że obiekt zatrzymał się w miejscu, podczas gdy holenderska i niemiecka konkurencja wyraźnie przyspieszyła. Część infrastruktury nosi ślady lat, a program ceremonii nie ma dziś nic, czego nie znajdziesz bliżej i taniej."}]},{"type":"paragraph","content":[{"type":"text","text":"To nadal dobry adres na spokojny dzień — po prostu nie jest już tym, czym był dekadę temu."}]}]}'::jsonb, 7.6, 75, 'published', now()),
  ('termy-maltanskie-recenzja', 'Recenzja', 'pc4', 'Miejski kompromis z ambitną strefą saun', 'Wygodny miejski adres, ale aufguss walczy tu o uwagę z aquaparkiem.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Termy Maltańskie mają zaletę, której nie kupi się żadną inwestycją: są w mieście, łatwo dostępne i można tu wpaść po pracy. Dla lokalnej społeczności saunowej to realna wartość."}]},{"type":"paragraph","content":[{"type":"text","text":"Strefa saun jest większa i ambitniejsza, niż sugerowałby profil obiektu. Program ceremonii istnieje, jest prowadzony regularnie, a część saunamistrzów naprawdę stara się wyjść poza standard."}]},{"type":"paragraph","content":[{"type":"text","text":"Charakter obiektu robi jednak swoje. To przede wszystkim duży kompleks basenowy, w którym sauny są jedną ze stref, a nie sercem miejsca. Odbija się to na atmosferze — o ciszę bywa trudno, zwłaszcza popołudniami."}]},{"type":"paragraph","content":[{"type":"text","text":"Traktuję to miejsce jako solidny wybór miejski, nie jako cel wyprawy. W tej roli sprawdza się dobrze i nie ma powodu, by od niego stronić."}]}]}'::jsonb, 7.2, 9, 'published', now()),
  ('polska-potega', 'Felieton', 'pc4', 'Dlaczego Polska stała się saunową potęgą Europy', 'W pięć lat przeszliśmy drogę, którą inne kraje pokonywały dekadę.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jeszcze niedawno aufguss w Polsce był niszą dla wtajemniczonych. Dziś mamy własne mistrzostwa, obiekty inwestujące w saunamistrzów i publiczność, która rozumie ceremonię i potrafi ją docenić."}]},{"type":"paragraph","content":[{"type":"text","text":"Zadecydowało kilka rzeczy naraz: fala nowych, ambitnych obiektów termalnych, pokolenie saunamistrzów z międzynarodowymi sukcesami oraz społeczność, która zamieniła saunowanie w styl życia."}]},{"type":"paragraph","content":[{"type":"text","text":"Co może nas zatrzymać? Przede wszystkim ryzyko, że komercja wyprzedzi rzemiosło. Dopóki jednak w centrum pozostaje jakość ceremonii, kierunek jest znakomity."}]}]}'::jsonb, null, null, 'published', now()),
  ('pts-classic-zapisy', 'Turnieje', 'pc2', 'Ruszają zapisy na Mistrzostwa Polski PTS Classic 2026', 'Rejestracja zawodników otwarta do końca lipca. Wielki finał w Słupsku.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Zapraszamy saunamistrzów do rejestracji na tegoroczne Mistrzostwa Polski PTS Classic. Eliminacje regionalne ruszają jesienią, a wielki finał odbędzie się w Słupsku."}]},{"type":"paragraph","content":[{"type":"text","text":"W tym roku spodziewamy się rekordowej frekwencji — zarówno wśród doświadczonych zawodników, jak i debiutantów. Regulamin oraz formularz zgłoszeniowy dostępne są w panelu zawodnika."}]},{"type":"paragraph","content":[{"type":"text","text":"To najważniejszy krajowy turniej w kalendarzu, a dla wielu saunamistrzów przepustka na areny międzynarodowe."}]}]}'::jsonb, null, null, 'published', now()),
  ('pts-nowy-ranking', 'Społeczność', 'pc3', 'Rusza 10-stopniowy system rang saunamistrzów', 'Wspólnie z aufguss.world wdrażamy skalę rang liczoną z punktów za turnieje.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Od teraz osiągnięcia z turniejów przekładają się na rangę widoczną na profilu zawodnika — od Rookie aż po Pro Master. Punkty naliczane są automatycznie na podstawie wyników."}]},{"type":"paragraph","content":[{"type":"text","text":"System ma uporządkować scenę i dać obiektom oraz publiczności czytelny sygnał o poziomie saunamistrza."}]},{"type":"paragraph","content":[{"type":"text","text":"To ważny krok w profesjonalizacji polskiej i europejskiej sceny aufguss."}]}]}'::jsonb, null, null, 'published', now()),
  ('satama-noc-aufguss', 'Wydarzenie', 'pc2', 'Noc aufguss z Robertem Zídkiem i Davidem Zatočilem', 'Wyjątkowy wieczór z dwoma mistrzami świata — bilety w sprzedaży od piątku.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Zapraszamy na wyjątkową noc aufguss z udziałem dwóch mistrzów świata. Wieczór wypełnią autorskie ceremonie, muzyka na żywo i specjalne rytuały przygotowane wyłącznie na tę okazję."}]},{"type":"paragraph","content":[{"type":"text","text":"Liczba miejsc jest ograniczona, a bilety trafią do sprzedaży w piątek. Rekomendujemy wcześniejszą rezerwację — poprzednie edycje wyprzedały się w kilka godzin."}]}]}'::jsonb, null, null, 'published', now()),
  ('satama-nowa-sauna', 'Obiekt', 'pc3', 'Nowa sauna zewnętrzna nad Scharmützelsee', 'Oddajemy do użytku panoramiczną saunę z widokiem na jezioro.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Nowa sauna zewnętrzna z tarasem widokowym jest już otwarta dla gości. Schłodzenie w jeziorze Scharmützelsee macie teraz na wyciągnięcie ręki."}]},{"type":"paragraph","content":[{"type":"text","text":"To kolejny etap rozbudowy resortu — stawiamy na połączenie natury z najwyższą jakością ceremonii aufguss."}]}]}'::jsonb, null, null, 'published', now()),
  ('satama-letni-program', 'Ceremonie', 'pc1', 'Letni program ceremonii — nowe aromaty', 'Cedr, mięta i cytrusy w odświeżonym planie ceremonii na lato.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Wraz z latem odświeżamy plan ceremonii. Do stałego repertuaru dołączają nowe kompozycje zapachowe: cedr syberyjski, mięta pieprzowa oraz orzeźwiające cytrusy z imbirem."}]},{"type":"paragraph","content":[{"type":"text","text":"Nowy grafik ceremonii znajdziecie w kalendarzu obiektu. Zapraszamy na saunowe lato."}]}]}'::jsonb, null, null, 'published', now()),
  ('zidek-mistrz-swiata', 'Turnieje', 'pc4', 'Robert Zídek po raz trzeci Mistrzem Świata Aufguss', 'Czeski saunamistrz obronił tytuł podczas The Battle of Gladiators w Termach Rzymskich w Czeladzi.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Robert Zídek po raz trzeci sięgnął po tytuł Mistrza Świata Aufguss. Finał The Battle of Gladiators rozegrano w Termach Rzymskich w Czeladzi, na słynnej Colosseum Arenie."}]},{"type":"paragraph","content":[{"type":"text","text":"Czeski saunamistrz pokonał silną, międzynarodową stawkę, prezentując dopracowany autorski program łączący choreografię, muzykę i perfekcyjną pracę parą."}]},{"type":"paragraph","content":[{"type":"text","text":"To kolejny dowód na to, że czeska i polska scena aufguss należą dziś do ścisłej światowej czołówki."}]}]}'::jsonb, null, null, 'published', now())
