-- aufguss.world — dane startowe (WYGENEROWANE: node supabase/generate-seed.js)
-- Nie edytować ręcznie: zmiany nanosić w data/*.js i wygenerować ponownie.
-- ═══════════════════════════════════════════════════════════════════════
begin;

-- Obiekty (107)
on conflict (id) do nothing;
-- Obiekty robocze (8) — obecne w wydarzeniach/turniejach, ale nie na mapie.
-- DO WERYFIKACJI: po sprawdzeniu ustawić status='published' i uzupełnić współrzędne.
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.venues','id'), (select max(id) from public.venues));

-- Saunamistrzowie (9) — byt, którego prototyp nie miał
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.saunamasters','id'), (select max(id) from public.saunamasters));

-- Saunamistrz ↔ obiekty (wiele obiektów, dokładnie jeden macierzysty)
on conflict do nothing;

-- Wydarzenia (25)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.events','id'), (select max(id) from public.events));

-- Obsada wydarzeń
on conflict do nothing;

-- Turnieje (9)
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.tournaments','id'), (select max(id) from public.tournaments));

-- Etapy turniejów
on conflict (id) do nothing;
select setval(pg_get_serial_sequence('public.tournament_stages','id'), (select max(id) from public.tournament_stages));

-- Zgłoszenia w etapach

-- Archiwum wyników (podium)
on conflict do nothing;

-- Wpisy (19) — body jako dokument ProseMirror
on conflict (slug) do nothing;

commit;

-- Podsumowanie: obiekty 107, saunamistrzowie 9, wydarzenia 25, turnieje 9, wpisy 19